// Site-specific rules for rankmehigher.com, ported from the old server: Caddy block
// /opt/n8n/sites.d/rankmehigher.caddy (www -> apex, handled by ALIAS_HOSTS) in front of
// the Express server.js in this repo.
//
// What server.js did and where it lives now:
//   - slashless marketing URL 301s + app-route rewrites to spa.html -> dist/_redirects
//     (generated by seo/routes.js; Workers static assets apply it like Cloudflare Pages)
//   - X-Robots-Tag on /free-website-audit -> public/_headers
//   - dotfiles 404 -> public/.assetsignore
//   - security headers on every response -> SECURITY_HEADERS below
//   - /api/* (lead-notify, AVA screening, applicants, script tools, PTO / team-task /
//     editor notifications) -> still the Express app on the VPS. It has no public
//     hostname of its own yet; add it to PROXIES once one exists (see the PR).

// Exact-path 301s: { '/old-path': '/new-path' }. Matching ignores a trailing slash.
const EXACT = {};

// Prefix 301s, e.g. Caddy `redir /category/news* /blog 301`: [['/category/news', '/blog']]
const PREFIX = [];

export function redirect(url) {
  const path = url.pathname.length > 1 ? url.pathname.replace(/\/+$/, '') : url.pathname;
  let to = EXACT[path];
  // Caddy `redir /x* ...` is a plain string-prefix match, so this is too.
  if (!to) for (const [from, dest] of PREFIX) if (path.startsWith(from)) { to = dest; break; }
  if (!to) return null;
  const dest = new URL(to, url);
  if (!to.includes('?')) dest.search = url.search;
  return Response.redirect(dest.toString(), 301);
}

// Paths still served by a VPS service: [{ prefix: '/api/', origin: 'https://something.andriusdigital.com' }]
// TODO before the DNS swap: /api/ -> the `rankmehigher` container (server.js, port 5000),
// which today is only reachable as rankmehigher.com itself.
export const PROXIES = [];

// Headers server.js set on every response (only added when the asset didn't set them).
export const SECURITY_HEADERS = {
  'X-Frame-Options': 'DENY',
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=()',
};
